import sqlite3

conn = sqlite3.connect(":memory:")
conn.executescript("""
CREATE TABLE fact (sale_id INTEGER, product_key INTEGER, cents INTEGER);
CREATE TABLE product (product_key INTEGER, category TEXT);
INSERT INTO fact VALUES (1, 1, 500), (2, 2, 700), (3, 1, 300), (4, 2, 100);
INSERT INTO product VALUES (1, 'books'), (2, 'games');
CREATE VIEW vw_sales AS SELECT f.sale_id, p.category, f.cents FROM fact f JOIN product p ON p.product_key = f.product_key;
""")
for row in conn.execute("SELECT category, SUM(cents) FROM vw_sales GROUP BY category ORDER BY category"):
    print(row)

WITH monthly(month, revenue) AS (VALUES (1, 2500), (2, 4000), (3, 4500))
SELECT month, revenue, round(100.0 * revenue / sum(revenue) OVER (), 1) AS share_pct
FROM monthly ORDER BY month;

WITH monthly(month, revenue) AS (VALUES (1, 2500), (2, 4000), (3, 3500))
SELECT month, revenue, revenue - lag(revenue) OVER (ORDER BY month) AS change
FROM monthly ORDER BY month;

def aov(amounts):
    if not amounts:
        return None
    return round(sum(amounts) / len(amounts))

print(aov([1000, 500, 750]))
print(aov([1001, 1002]))
print(aov([]))
